{en:"sublation",ph:"səˈbleɪʃn",ru:"снятие (гегелевское)",ex:"Sublation is the English term for Hegel's Aufhebung.",lv:"C2",cat:"philosophy"},
{en:"immanence",ph:"ˈɪmənəns",ru:"имманентность",ex:"Spinoza's God is immanent within nature rather than transcendent above it.",lv:"C2",cat:"philosophy"},
{en:"transcendence",ph:"trænˈsendəns",ru:"трансцендентность",ex:"For Kant, God and freedom belong to the realm of transcendence.",lv:"C2",cat:"philosophy"},
{en:"apeiron",ph:"əˈpeɪrɒn",ru:"апейрон; беспредельное",ex:"Anaximander posited the apeiron as the infinite principle underlying all things.",lv:"C2",cat:"philosophy"},
{en:"panentheism",ph:"ˌpænənˈθiːɪzəm",ru:"панентеизм",ex:"Panentheism holds that the universe is part of but does not exhaust God.",lv:"C2",cat:"philosophy"},
{en:"panpsychism",ph:"ˌpænˈsaɪkɪzəm",ru:"панпсихизм",ex:"Panpsychism attributes some form of mind to all constituents of matter.",lv:"C2",cat:"philosophy"},
{en:"numinous",ph:"ˈnjuːmɪnəs",ru:"нуминозное; священное",ex:"Rudolf Otto described the numinous as the awe-inspiring core of religious experience.",lv:"C2",cat:"philosophy"},
{en:"elenchus",ph:"ɪˈleŋkəs",ru:"элегх; сократовское опровержение",ex:"Socrates used elenchus to expose the contradictions in his opponents' beliefs.",lv:"C2",cat:"philosophy"},
{en:"maieutics",ph:"meɪˈjuːtɪks",ru:"майевтика; повивальное искусство Сократа",ex:"Maieutics draws out knowledge the student already possesses through questioning.",lv:"C2",cat:"philosophy"},
{en:"parousia",ph:"pəˈruːsiə",ru:"парусия; пришествие; присутствие",ex:"Derrida critiques the metaphysics of parousia, the ideal of pure presence.",lv:"C2",cat:"philosophy"},
{en:"hypostasis",ph:"haɪˈpɒstəsɪs",ru:"ипостась",ex:"In Neoplatonism, the hypostases are the levels of reality emanating from the One.",lv:"C2",cat:"philosophy"},
{en:"kenosis",ph:"kɪˈnəʊsɪs",ru:"кенозис; самоопустошение",ex:"Kenosis describes divine self-emptying in becoming finite.",lv:"C2",cat:"philosophy"},
{en:"eschatology",ph:"ˌeskəˈtɒlədʒi",ru:"эсхатология",ex:"Eschatology addresses questions about death, judgement, and the end of history.",lv:"C2",cat:"philosophy"},
{en:"theodicy",ph:"θɪˈɒdɪsi",ru:"теодицея",ex:"Leibniz's theodicy attempted to reconcile God's goodness with the existence of evil.",lv:"C2",cat:"philosophy"},
{en:"axiology",ph:"ˌæksiˈɒlədʒi",ru:"аксиология; теория ценностей",ex:"Axiology explores the nature, criteria, and metaphysics of value.",lv:"C2",cat:"philosophy"},
{en:"deontic logic",ph:"dɪˈɒntɪk ˈlɒdʒɪk",ru:"деонтическая логика",ex:"Deontic logic formalises reasoning about obligation, permission, and prohibition.",lv:"C2",cat:"philosophy"},
{en:"modal realism",ph:"ˈməʊdl ˈrɪəlɪzəm",ru:"модальный реализм",ex:"David Lewis defended modal realism, the view that possible worlds are concretely real.",lv:"C2",cat:"philosophy"},
{en:"truthmaker theory",ph:"ˈtruːθmeɪkər ˈθɪəri",ru:"теория создателей истины",ex:"Truthmaker theory asks what in the world makes propositions true.",lv:"C2",cat:"philosophy"},
{en:"supervenience",ph:"ˌsuːpəˈviːniəns",ru:"супервентность",ex:"Mental properties supervene on physical properties without being reducible to them.",lv:"C2",cat:"philosophy"},
{en:"qualia",ph:"ˈkweɪliə",ru:"квалиа",ex:"The redness of red as you experience it is an example of a quale.",lv:"C2",cat:"philosophy"},
{en:"hard problem of consciousness",ph:"hɑːd ˈprɒbləm əv ˈkɒnʃəsnəs",ru:"трудная проблема сознания",ex:"Chalmers' hard problem asks why physical processes produce subjective experience.",lv:"C2",cat:"philosophy"},
{en:"epiphenomenalism",ph:"ˌepɪfɪˈnɒmɪnəlɪzəm",ru:"эпифеноменализм",ex:"Epiphenomenalism treats consciousness as a byproduct of brain activity with no causal power.",lv:"C2",cat:"philosophy"},
{en:"eliminative materialism",ph:"ɪˈlɪmɪnətɪv məˈtɪəriəlɪzəm",ru:"элиминативный материализм",ex:"Eliminative materialism holds that folk psychological concepts will be replaced by neuroscience.",lv:"C2",cat:"philosophy"},
{en:"compatibilism",ph:"kəmˈpætɪbɪlɪzəm",ru:"компатибилизм",ex:"Compatibilism argues that free will and determinism are not mutually exclusive.",lv:"C2",cat:"philosophy"},
{en:"incompatibilism",ph:"ˌɪnkəmˈpætɪbɪlɪzəm",ru:"инкомпатибилизм",ex:"Incompatibilism holds that genuine free will requires the falsity of determinism.",lv:"C2",cat:"philosophy"},
{en:"occasionalism",ph:"əˈkeɪʒənəlɪzəm",ru:"окказионализм",ex:"Occasionalism holds that God is the direct cause of all apparent interactions between mind and body.",lv:"C2",cat:"philosophy"},
{en:"panopticism",ph:"pæˈnɒptɪsɪzəm",ru:"паноптицизм (Фуко)",ex:"Foucault's panopticism describes how surveillance disciplines behaviour.",lv:"C1",cat:"philosophy"},
{en:"verisimilitude",ph:"ˌverɪsɪˈmɪlɪtjuːd",ru:"правдоподобие (Поппер)",ex:"Popper used verisimilitude to measure how close a theory is to the truth.",lv:"C2",cat:"literature"},
{en:"enargeia",ph:"ɪˈnɑːdʒɪə",ru:"энаргейя; живописность описания",ex:"Ancient rhetorical theory prized enargeia, the vividness that makes a scene present to the mind.",lv:"C2",cat:"literature"},
{en:"factuality",ph:"fækˈtʃuːəlɪti",ru:"фактуальность; документальность",ex:"The journalist's factuality was never questioned despite the sensitivity of the story.",lv:"C1",cat:"media"},
{en:"narrowcasting",ph:"ˈnærəʊkɑːstɪŋ",ru:"нишевое вещание",ex:"Narrowcasting targets content at specific demographic or interest groups.",lv:"C2",cat:"media"},
{en:"remediation",ph:"ˌriːmiːdiˈeɪʃn",ru:"ремедиация; переформатирование контента",ex:"Remediation describes how new media absorb and refashion older media forms.",lv:"C2",cat:"media"},
{en:"hypermediacy",ph:"ˌhaɪpəˈmiːdiəsi",ru:"гипермедиальность",ex:"Hypermediacy foregrounds the medium itself rather than creating a transparent window.",lv:"C2",cat:"media"},
{en:"immediacy",ph:"ɪˈmiːdiəsi",ru:"непосредственность (медиа)",ex:"Television strives for immediacy, making the viewer feel present at events.",lv:"C2",cat:"media"},
{en:"wetland",ph:"ˈwetlənd",ru:"заболоченные угодья; водно-болотные угодья",ex:"Wetlands filter pollutants and provide habitat for rare amphibians.",lv:"C1",cat:"nature"},
